CREATE TABLE IF NOT EXISTS rm_workspace_authorization_events (
 id INTEGER PRIMARY KEY,
 actor TEXT NOT NULL CHECK(length(actor) BETWEEN 6 AND 160 AND substr(actor, 1, 5) = 'user:' AND substr(actor, 6) NOT GLOB '*[^A-Za-z0-9._-]*'),
 method TEXT NOT NULL CHECK(method IN ('GET','POST','PATCH','PUT','DELETE')),
 route_template TEXT NOT NULL CHECK(length(route_template) BETWEEN 5 AND 240 AND substr(route_template,1,5) = '/api/' AND route_template NOT GLOB '*[^A-Za-z0-9_/:.-]*'),
 permission TEXT NOT NULL CHECK(length(permission) BETWEEN 3 AND 80 AND permission NOT GLOB '*[^a-z0-9._-]*'),
 company_slug TEXT CHECK(company_slug IS NULL OR (length(company_slug) BETWEEN 1 AND 120 AND substr(company_slug,1,1) GLOB '[a-z0-9]' AND company_slug NOT GLOB '*[^a-z0-9-]*')),
 outcome TEXT NOT NULL CHECK(outcome = 'denied'),
 reason_code TEXT NOT NULL CHECK(reason_code = 'authorization_denied'),
 request_id TEXT CHECK(request_id IS NULL OR (length(request_id) BETWEEN 1 AND 64 AND substr(request_id,1,1) GLOB '[A-Za-z0-9]' AND request_id NOT GLOB '*[^A-Za-z0-9._-]*')),
 created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS rm_workspace_authorization_events_lookup ON rm_workspace_authorization_events(actor, company_slug, id DESC);
CREATE TRIGGER IF NOT EXISTS rm_workspace_authorization_events_no_update BEFORE UPDATE ON rm_workspace_authorization_events BEGIN SELECT RAISE(ABORT, 'workspace authorization events are append-only'); END;
CREATE TRIGGER IF NOT EXISTS rm_workspace_authorization_events_no_delete BEFORE DELETE ON rm_workspace_authorization_events BEGIN SELECT RAISE(ABORT, 'workspace authorization events are append-only'); END;
